    showFormError(form,error){let box=form.querySelector('.form-error');if(!box){box=document.createElement('div');box.className='danger-box form-error';form.prepend(box)}const explanation=error.details?.explanation;if(explanation){box.innerHTML=`<b>${CoreUtil.escape(error.code||'CONFLICT')}</b><div>${CoreUtil.escape(error.message)}</div><h3>Reason</h3>${explanation.conflicts.map(conflict=>`<div><b>${CoreUtil.escape(conflict.classification)}</b> — ${CoreUtil.escape(conflict.message)}</div>`).join('')}<div class="flow-gap-8"><b>Requested duration</b> ${CoreUtil.duration(explanation.requestedMinutes)}</div>${explanation.alternatives.length?`<h3>Alternatives</h3><ul>${explanation.alternatives.map(item=>`<li>${CoreUtil.formatDate(item.date)} ${item.startTime}–${item.endTime}</li>`).join('')}</ul>`:''}`}else box.textContent=`${error.code||'VALIDATION'}: ${error.message}`;const mapping={title:'title',minimum:'minimumSessionMinutes',maximum:'maximumSessionMinutes',weekly:'weeklyTargetHours',target:'weeklyTargetHours',date:'endDate',sleep:'sleepBedtime'};for(const [word,name] of Object.entries(mapping))if(error.message.toLowerCase().includes(word)){const field=form.querySelector(`[name="${name}"]`);field?.setAttribute('aria-invalid','true');field?.focus();break}}
    async onChange(event){const element=event.target;if(element.matches('[data-setting]')){const key=element.dataset.setting,value=element.type==='checkbox'?element.checked:element.type==='number'?Number(element.value):element.value;try{const settings=await this.repo.settings();DataValidator.settings({...settings,[key]:value});await this.repo.setting(key,value);if(key==='theme')await this.applyTheme();await this.notifications.notify('SUCCESS','Setting saved');if(['uiMode','theme','autoSnapshots'].includes(key))await this.render()}catch(error){element.setAttribute('aria-invalid','true');await this.notifyError(error,'Settings')}}if(element.matches('[data-task-select]')){const selected=new Set(this.state.get('selectedTasks'));element.checked?selected.add(element.dataset.taskSelect):selected.delete(element.dataset.taskSelect);this.state.set({selectedTasks:selected});this.updateBulkBar()}if(element.matches('[data-template-sleep-policy],[name="sleepBedtime"],[name="sleepWakeTime"],[name="dayType"]'))this.updateTemplateSleepPreview()}
    onInput(event){if(event.target.id==='settingsSearch'){this.state.set({settingsFilter:event.target.value});this.filterSettings(event.target.value)}if(event.target.id==='globalSearch'){clearTimeout(this.searchTimer);const value=event.target.value;this.searchTimer=setTimeout(()=>this.performSearch(value),90)}if(event.target.id==='paletteInput')this.renderPalette(event.target.value);if(event.target.closest('form')){event.target.removeAttribute('aria-invalid');event.target.closest('form').querySelector('.form-error')?.remove();this.inlineValidate(event.target.closest('form'))}}
