    onKeyDown(event){if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();this.openPalette();return}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='z'){event.preventDefault();event.shiftKey?this.undo.redo().then(()=>this.render()):this.undo.undo().then(()=>this.render());return}if(event.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){event.preventDefault();document.getElementById('globalSearch').focus();return}const search=document.getElementById('globalSearch');if(document.activeElement===search&&this.searchResults.length){if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();this.state.set({searchIndex:CoreUtil.clamp(this.state.get('searchIndex')+(event.key==='ArrowDown'?1:-1),0,this.searchResults.length-1)});this.drawSearchResults()}else if(event.key==='Enter'){event.preventDefault();const result=this.searchResults[this.state.get('searchIndex')];if(result)this.openRecord(result.store,result.recordId)}else if(event.key==='Escape')this.closeSearch()}const palette=document.getElementById('paletteDialog');if(palette.open){if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();this.state.set({paletteIndex:CoreUtil.clamp(this.state.get('paletteIndex')+(event.key==='ArrowDown'?1:-1),0,this.paletteCommands.length-1)});this.drawPalette()}else if(event.key==='Enter'){event.preventDefault();this.executePalette(this.paletteCommands[this.state.get('paletteIndex')])}}}
    onDragStart(event){const item=event.target.closest('[draggable][data-task-id]');if(item)event.dataTransfer.setData('application/x-lifeos-task',item.dataset.taskId)}
