    onResizePointerDown(event){const handle=event.target.closest('[data-resize-block]');if(!handle||event.isPrimary===false)return;event.preventDefault();event.stopPropagation();const originalDuration=CoreUtil.num(handle.dataset.duration),startTime=handle.dataset.startTime;if(!originalDuration||CoreUtil.clock(startTime)===null)return;this.cancelCalendarResize();const entry=handle.closest('[data-calendar-block]'),preview=entry?.querySelector('.resize-preview');this.resizeSession={pointerId:event.pointerId,blockId:handle.dataset.resizeBlock,startY:event.clientY,originalDuration,previewDuration:originalDuration,startTime,handle,entry,preview,pointerType:event.pointerType||'mouse'};entry?.classList.add('resizing');try{handle.setPointerCapture(event.pointerId)}catch{}this.updateCalendarResizePreview(this.resizeSession)}
