    cancelCalendarResize(event=null){const session=this.resizeSession;if(!session||event&&event.pointerId!==session.pointerId)return;this.resizeSession=null;session.entry?.classList.remove('resizing');if(session.preview)session.preview.textContent=''}
    updateCalendarResizePreview(session){if(!session.preview)return;const start=CoreUtil.clock(session.startTime),end=start+session.previewDuration,nextDay=end>1440?' · next day':'';session.preview.textContent=`Preview ${session.startTime}–${CoreUtil.time(end)}${nextDay} · ${CoreUtil.duration(session.previewDuration)}`}
    async commitCalendarResize(id,duration,{pointerType='pointer'}={}){const old=await this.repo.get('timeBlocks',id);if(!old)throw CoreUtil.error('CAL-RESIZE-001','The scheduled block no longer exists.');if(old.protected||old.type==='sleep'||old.sleepGenerated||old.templateGenerated||old.dayTemplateId)throw CoreUtil.error('SLEEP-PROTECTED-004','Protected or template-owned time must be changed through its owning Day Template.');if(old.locked)throw CoreUtil.error('CAL-RESIZE-LOCKED-002','Unlock this block before resizing it.');const task=old.taskId?await this.repo.get('tasks',old.taskId):null,data=await this.data(),settings=await this.repo.settings(),candidate=TimeInterval.fromParts({sourceType:'timeBlock',sourceId:old.id,startDate:old.date,startTime:old.startTime,duration,locked:false,category:old.type==='task'?'task':old.type||'routine',lifeAreaId:old.lifeAreaId,projectId:old.projectId||task?.projectId}),conflicts=ConflictEngine.checkInterval(candidate,data,settings,{task,ignoreIds:[old.id]});if(conflicts.some(item=>item.type!=='soft'))throw CoreUtil.error(conflicts[0].code,conflicts[0].message,{conflicts,explanation:ExplanationEngine.conflict(task||{title:old.title,estimatedDuration:duration},conflicts,[])});const oldEnd=old.endTime||CoreUtil.time(CoreUtil.clock(old.startTime)+CoreUtil.num(old.duration)),newEnd=CoreUtil.time(CoreUtil.clock(old.startTime)+duration),after=this.repo.stamp('timeBlocks',{...old,duration,endTime:newEnd,manuallyPlaced:true,sourceType:'user',sourceId:old.id,resizeInput:pointerType},old),label=`Resized “${old.title}” ${old.startTime}–${oldEnd} → ${old.startTime}–${newEnd}`;await this.undo.execute(label,[{store:'timeBlocks',id:old.id,before:old,after}],{activityType:'block-resize',meta:{pointerType}});await this.notifications.notify('SUCCESS',`Resized “${old.title}”`,`${old.startTime}–${newEnd}`);await this.render();return after}

    openQuickAdd(){this.modal.open('Create',`<div class="grid grid-2"><button class="btn primary" data-action="new-task">Task</button><button class="btn" data-action="new-event">Event</button><button class="btn" data-action="new-project">Project</button><button class="btn" data-action="new-goal">Goal</button><button class="btn" data-action="new-habit">Habit</button><button class="btn" data-action="new-template">Day Template</button></div>`)}
    async quickCapture(){const input=document.getElementById('quickCapture'),text=input.value.trim();if(!text)return;const durationMatch=text.match(/(\d+)\s*(?:min|m)\b/i),dateMatch=text.match(/\b(today|tomorrow|monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b/i),deadline=dateMatch?this.parseNaturalDate(dateMatch[1]):'',title=text.replace(durationMatch?.[0]||'','').replace(dateMatch?.[0]||'','').trim();await this.service.saveTask({title,estimatedDuration:durationMatch?Number(durationMatch[1]):45,status:'Inbox',priority:'Medium',deadline,minimumSessionDuration:15,maximumSessionDuration:90});input.value='';await this.render()}
