    async completeTask(id){const task=await this.repo.get('tasks',id);if(!task)return;const after=this.repo.stamp('tasks',{...task,status:'Completed',completedAt:CoreUtil.nowISO()},task);await this.undo.execute(`Completed task “${task.title}”`,[{store:'tasks',id,before:task,after}],{activityType:'task-complete'});await this.render()}
