    async previewDay(rescue,minimum){const [data,settings]=await Promise.all([this.data(),this.repo.settings()]),model=PersonalPlanningModel.build(data),plan=new DayScheduler(data,settings,model).generate(CoreUtil.localDate(),{rescue,minimum});if(!plan.planned.length&&!plan.remove.length){const blocked=plan.skipped.slice(0,4),body=`<div class="warning"><b>No realistic changes fit.</b><div>Protected sleep, locked commitments, physical capacity, dependencies and session limits were preserved.</div></div>${blocked.length?`<h3 class="flow-gap-14">Why tasks were skipped</h3><div class="list">${blocked.map(item=>`<div class="item"><div class="item-main"><b>${CoreUtil.escape(item.task.title)}</b><div class="muted">${CoreUtil.escape(item.reason)}</div></div></div>`).join('')}</div>`:''}`;this.modal.open(rescue?'Rescue My Day':minimum?'Minimum Day':'Generate My Day',body,'<button class="btn primary" data-action="close-dialog">Close</button>');return}this.state.set({pending:{type:'day',plan}});this.modal.open(rescue?'Rescue My Day preview':minimum?'Minimum Day preview':'Generate My Day preview',this.schedulePreviewHTML(plan),`<button class="btn" data-action="close-dialog">Cancel</button><button class="btn primary" data-action="apply-day-plan">Apply plan</button>`,{subtitle:'Nothing changes until you apply.'})}
    schedulePreviewHTML(plan){return`<div class="operation-preview"><div><b>${plan.summary.created}</b><small>Created</small></div><div><b>${plan.summary.moved}</b><small>Moved</small></div><div><b>${plan.summary.removed}</b><small>Removed</small></div><div><b>${plan.summary.deadlinesImproved}</b><small>Deadlines helped</small></div></div><h3 class="flow-gap-16">Proposed schedule</h3><div class="list">${plan.planned.map(item=>`<div class="item"><div class="item-main"><b>${item.block.startTime}–${item.block.endTime} · ${CoreUtil.escape(item.task.title)}</b><div class="muted">${CoreUtil.escape(item.explanation.reasons.join(' · '))}</div></div><button class="btn small" type="button" data-action="explain-schedule" data-id="${item.block.id}">Why?</button></div>`).join('')||'<p class="muted">No blocks created.</p>'}</div>${plan.remove.length?`<div class="warning flow-gap-12"><b>${plan.remove.length} generated flexible block${plan.remove.length===1?'':'s'} will be removed.</b><div>User-created, manually placed, locked and protected blocks remain unchanged.</div></div>`:''}${plan.skipped.length?`<details class="flow-gap-12"><summary>${plan.skipped.length} skipped task${plan.skipped.length===1?'':'s'}</summary><div class="list">${plan.skipped.slice(0,10).map(item=>`<div class="item"><div class="item-main"><b>${CoreUtil.escape(item.task.title)}</b><div class="muted">${CoreUtil.escape(item.reason)}</div></div></div>`).join('')}</div></details>`:''}`}
    async explainPendingSchedule(blockId){const pending=this.state.get('pending'),item=pending?.plan?.planned?.find(value=>value.block.id===blockId);if(!item)return;const data=await this.data(),settings=await this.repo.settings(),alternatives=ConflictEngine.alternatives(item.task,CoreUtil.addDays(item.block.date,1),data,settings);this.modal.open(item.explanation.title,`<h2>${CoreUtil.escape(item.task.title)}</h2><p><b>${CoreUtil.formatDate(item.block.date)} ${item.block.startTime}–${item.block.endTime}</b></p><h3>Reasons</h3><ul>${item.explanation.reasons.map(reason=>`<li>+ ${CoreUtil.escape(reason)}</li>`).join('')}</ul>${item.explanation.avoided.length?`<h3>Avoided</h3><ul>${item.explanation.avoided.map(reason=>`<li>${CoreUtil.escape(reason)}</li>`).join('')}</ul>`:''}${alternatives.length?`<h3>Other safe windows</h3><ul>${alternatives.map(value=>`<li>${CoreUtil.formatDate(value.date)} ${value.startTime}–${value.endTime}</li>`).join('')}</ul>`:''}<p class="muted">Scheduler ${SCHEDULER_VERSION} · deterministic centralized weights.</p>`,'<button class="btn primary" data-action="close-dialog">Close</button>')}
