    async resetData(){const snapshot=await this.snapshots.create('Before Reset','pre-reset',{protected:true}),stores=DOMAIN_STORES.concat(['activityLog','trash','notifications','systemMeta']).filter(store=>store!=='snapshots'),journal=await this.journal.begin('Reset data',stores,snapshot.id);try{await this.repo.transaction([...stores,'settings'],async tx=>{for(const store of stores)await tx.clear(store);await tx.clear('settings');await tx.put('settings',{...defaultSettings,id:'settings',databaseCreatedAt:CoreUtil.nowISO(),onboardingComplete:false,createdAt:CoreUtil.nowISO(),updatedAt:CoreUtil.nowISO(),revision:1})});await this.journal.finish(journal,'committed');this.modal.close();await this.seed();await this.render();await this.startOnboardingIfNeeded()}catch(error){await this.journal.finish(journal,'failed',error);throw error}}
