    showIntegrity(report){const serious=report.issues.filter(issue=>!issue.safe);this.modal.open('LifeOS System Health',`<div class="health-state ${report.status==='Critical'?'error':report.status==='Review'?'warning':''}">${report.status}</div><div class="stat-row block-gap-12"><div class="stat"><b>${report.recordsChecked}</b><div class="metric-label">Records checked</div></div><div class="stat"><b>${report.issues.length}</b><div class="metric-label">Issues</div></div><div class="stat"><b>${report.safeCount}</b><div class="metric-label">Safe issues</div></div><div class="stat"><b>${report.blockingCount}</b><div class="metric-label">Blocking</div></div></div>${report.issues.length?`<div class="list">${report.issues.slice(0,40).map(issue=>`<div class="item"><div class="item-main"><b>${CoreUtil.escape(issue.code)}</b><div>${CoreUtil.escape(issue.message)}</div><div class="item-meta"><span>${issue.severity}</span><span>${issue.safe?'Safe repair':'Manual review'}</span></div></div></div>`).join('')}</div>`:'<div class="success-box">No broken references, impossible intervals, duplicate IDs, invalid dependencies or schema violations were found.</div>'}`,`<button class="btn" data-action="close-dialog">Close</button>${report.safeCount?'<button class="btn" data-action="repair-integrity">Repair safe issues</button>':''}<button class="btn primary" data-action="run-self-test">Run self-test</button>`,{subtitle:serious.length?'Manual review is required for non-safe issues.':'Safe, non-destructive repair only.'})}
